WITH flattened AS (SELECT id, service, host, log_ts, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, attr_value) SELECT service, host, COUNT(DISTINCT id) AS distinct_ids, MIN(log_ts) AS first_log_ts, MAX(log_ts) AS ended_at, COUNT(DISTINCT id) AS distinct_ids_2 FROM flattened GROUP BY GROUPING SETS ((service, host), (service), ()) HAVING COUNT(DISTINCT id) > 1;
